const roles = {
  "PdM（產品經理）": "決定『做什麼』—產品方向、優先序、為什麼做",
  "PM（專案經理）": "決定『怎麼做』—時程、資源、把事推到上線",
};
for (const [r, job] of Object.entries(roles)) console.log(r + "\n  " + job);

const duties = {
  Discovery: "挖需求—使用者到底要什麼",
  Definition: "定義—要做什麼、怎麼算成功（寫 PRD）",
  Delivery: "交付—盯著做出來、上線",
};
for (const [k, v] of Object.entries(duties)) console.log(k + ": " + v);

// JTBD：使用者不是買產品，是「雇用它完成某個任務」
const jtbd = [
  { 買: "電鑽", 真正想要: "牆上一個洞" },
  { 買: "奶昔", 真正想要: "開車通勤時不無聊又不餓" },
];
jtbd.forEach(j => console.log("買「" + j.買 + "」其實是想要：" + j.真正想要));
console.log("=> 搞懂真正的『任務』，才做對產品");

// 用戶研究 = 質化（訪談）+ 量化（數據）
const methods = { "質化": ["1對1訪談", "可用性測試"], "量化": ["問卷", "行為數據分析"] };
for (const [type, ms] of Object.entries(methods)) console.log(type + "：" + ms.join("、"));
console.log("兩個一起，才不會憑直覺或老闆說了算");

// PRD：把需求講清楚，工程師看了就能動工
const prd = {
  問題: "新用戶不知道怎麼開始",
  目標: "讓 80% 新用戶 3 分鐘內完成第一個動作",
  範圍: ["引導步驟", "範例專案"],
  成功指標: "新用戶 7 日留存 +20%",
};
for (const [k, v] of Object.entries(prd)) console.log(k + "：" + (Array.isArray(v) ? v.join("、") : v));
